let queueResult=null,queueBusy=false;
function renderQueue(){const w=queueWords[language]||queueWords.en;$('queue-check').textContent=w[0];$('queue-check').disabled=busy||queueBusy;$('queue-note').textContent=w[5];let result=queueBusy?w[1]:'';if(!queueBusy&&queueResult){result=w[{'queued-observed':2,'none-observed':3,unknown:4}[queueResult.status]??4];if(queueResult.checked_at)result+=' · '+new Date(queueResult.checked_at).toLocaleString(language);}$('queue-result').textContent=result;}
