let sendingDNSResult=null,sendingDNSBusy=false,sendingDNSGeneration=0;
function renderSendingDNS(){const w=sendingDNSWords[language]||sendingDNSWords.en;$('sending-domain-label').textContent=w[0];$('sending-selector-label').textContent=w[1];$('sending-dns-check').textContent=w[2];$('sending-dns-check').disabled=sendingDNSBusy||busy;$('sending-dns-note').textContent=w[9];let result='';
 if(sendingDNSBusy)result=w[3];else if(sendingDNSResult){if(sendingDNSResult.invalid)result=w[8];else{for(const key of ['spf','dmarc','dkim']){const status=sendingDNSResult[key];if(key==='dkim'&&status==='not-configured')continue;const index={observed:4,'not-found':5,multiple:6,unknown:7}[status]??7;result+=(result?' · ':'')+key.toUpperCase()+': '+w[index];}if(sendingDNSResult.checked_at)result+=' · '+new Date(sendingDNSResult.checked_at).toLocaleString(language);}}
 $('sending-dns-result').textContent=result;}
let dnsResult=null,dnsBusy=false,dnsGeneration=0;
function renderDNS(){const w=dnsWords[language]||dnsWords.en,x=dnsExpectedWords[language]||dnsExpectedWords.en;$('dns-expected-label').textContent=x[0];$('dns-check').textContent=w[0];$('dns-check').disabled=dnsBusy||busy;let result='';
 if(dnsBusy)result=w[1];else if(dnsResult){const index={observed:2,'not-found':3,unknown:4,invalid:6}[dnsResult.status]??4;const nullWords=dnsNullWords[language]||dnsNullWords.en;result=dnsResult.status==='null-mx'?nullWords[0]:dnsResult.status==='invalid-mx'?nullWords[1]:w[index];
  if(['observed','null-mx','invalid-mx'].includes(dnsResult.status)){const a=dnsAddressWords[language]||dnsAddressWords.en;result+=': '+dnsResult.records.map(v=>{let value=`${v.preference} ${v.host}`;for(const [key,label] of [['a','A'],['aaaa','AAAA']]){const status=v[key+'_status'];if(status==='observed')value+=` (${label}: ${(v[key]||[]).join(', ')})`;else if(status==='not-found')value+=` (${label}: ${a[1]})`;else if(status)value+=` (${label}: ${a[2]})`;}return value;}).join(', ');}
  if(dnsResult.expected_mx){const index={observed:1,'not-observed':2,unknown:3}[dnsResult.expected_status]??3;result+=' · '+x[index]+': '+dnsResult.expected_mx;}
  if(dnsResult.checked_at)result+=' · '+new Date(dnsResult.checked_at).toLocaleString(language);
  if(dnsResult.status!=='invalid')result+=' · '+w[5];}
 $('dns-result').textContent=result;}
