function renderOutboundProbe(){const labels=outboundProbeWords[language]||outboundProbeWords.en,w=vpsProbeWords[language]||vpsProbeWords.en,p=smtpProbeGuide[language]||smtpProbeGuide.en;
 $('outbound-probe').hidden=!['smtp','resend'].includes($('provider').value);$('outbound-probe-check').textContent=labels[0];$('outbound-probe-check').disabled=busy||outboundProbeBusy;$('outbound-probe-note').textContent=labels[1];let output='';
 if(outboundProbeBusy)output=w[2];else if(outboundProbeResult){if(outboundProbeResult.invalid)output=w[3];else if(outboundProbeResult.error)output=w[4];else{const statuses={'smtp-greeting':6,refused:7,'unexpected-banner':8,'non-public':9,unknown:4},tls={verified:3,'not-advertised':4,'invalid-certificate':5,unknown:6};output=['ipv4','ipv6'].map(family=>{const v=outboundProbeResult[family];return `${family==='ipv4'?'IPv4':'IPv6'}: `+(v?.status==='not-found'?w[5]:v?.status!=='observed'?w[4]:(v.addresses||[]).map(a=>`${a.address}: ${w[statuses[a.status]??4]}${a.tls?' / '+p[tls[a.tls]??6]:''}`).join(', '));}).join(' · ');if(outboundProbeResult.checked_at)output+=' · '+new Date(outboundProbeResult.checked_at).toLocaleString(language);}}
 $('outbound-probe-result').textContent=output;
}
