 if(vpsProbeBusy)output=w[2];else if(vpsProbeResult){if(vpsProbeResult.invalid)output=w[3];else if(vpsProbeResult.error)output=w[4];else {const statuses={'smtp-greeting':6,refused:7,'unexpected-banner':8,'non-public':9,unknown:4},tls={verified:3,'not-advertised':4,'invalid-certificate':5,unknown:6};output=['ipv4','ipv6'].map(family=>{const v=vpsProbeResult[family];return `${family==='ipv4'?'IPv4':'IPv6'}: `+(v?.status==='not-found'?w[5]:v?.status!=='observed'?w[4]:(v.addresses||[]).map(a=>`${a.address}: ${w[statuses[a.status]??4]}${a.status==='smtp-greeting'?' / '+p[tls[a.tls]??6]:''}`).join(', '));}).join(' · ');if(vpsProbeResult.checked_at)output+=' · '+new Date(vpsProbeResult.checked_at).toLocaleString(language);}}
