 $('outbound-password-field').hidden=$('provider').value==='direct';const ready=active&&!busy&&!workerBusy&&!relayBusy&&!vpsBusy&&!outboundDone&&!outboundBlocked&&savedDraft===JSON.stringify(collect())&&/^cfg-[0-9a-f]{32}$/.test($('outbound-operation').value);
