function renderWorker(){const w=workerWords[language]||workerWords.en;const active=workerAvailable&&$('inbound').value==='worker-r2';$('worker-installer').hidden=!active;
 for(const [id,index]of Object.entries({'worker-title':0,'worker-note':1,'worker-operation-label':2,'worker-capacity-label':3,'worker-drain-label':4,'worker-deploy-label':5,'worker-routing-label':6,'worker-prepare':7,'worker-commit':8}))$(id).textContent=w[index];
 const ready=active&&!workerBusy&&!relayBusy&&!vpsBusy&&!busy&&savedDraft===JSON.stringify(collect())&&$('limits_confirmed').checked;
 $('worker-prepare').disabled=!ready;$('worker-commit').disabled=!ready;
 $('worker-result').textContent=workerBusy?w[9]:workerResult?w[workerResult]+(workerResult===13&&workerUnknownOperation?' ('+workerUnknownOperation+')':''):active&&!ready?w[14]:'';}
